// Generated functions share the exact simulation equations with WebGL2.
fn readSpawn(mask: texture_2d<f32>, index: f32) -> f32 {
  let word = i32(index);
  let pixel = i32((f32(word) / 4f));
  let width = i32(textureDimensions(mask, 0).x);
  return textureLoad(mask, vec2i((pixel % width), i32((f32(pixel) / f32(width)))), 0)[(word % 4i)];
}

struct ParticleStep {
  seconds: f32,
  orientToMovement: f32,
  orientToAngularVelocity: f32,
  rotationCurve: f32,
  angularVelocityCurve: f32,
}

struct ParticleBirth {
  seed: f32,
  speed: f32,
  direction: f32,
  spread: f32,
  lifetime: f32,
  shapeType: f32,
  dimensionX: f32,
  dimensionY: f32,
  dimensionSpreadX: f32,
  dimensionSpreadY: f32,
  initialSize: f32,
  initialRotation: f32,
  initialStretchX: f32,
  initialStretchY: f32,
  initialRed: f32,
  initialGreen: f32,
  initialBlue: f32,
  initialAlpha: f32,
  speedSpread: f32,
  lifetimeSpread: f32,
  sizeSpread: f32,
  rotationSpread: f32,
  redSpread: f32,
  greenSpread: f32,
  blueSpread: f32,
  alphaSpread: f32,
  angularVelocitySpread: f32,
  stretchXSpread: f32,
  stretchYSpread: f32,
  emitterX: f32,
  emitterY: f32,
  inheritedVelocityX: f32,
  inheritedVelocityY: f32,
  emitterCosine: f32,
  emitterSine: f32,
  emitterScale: f32,
  handedness: f32,
  orientToDirection: f32,
  initialAngularVelocity: f32,
}

fn propertyVariation(particleId: f32, seed: f32, stream: i32) -> f32 {
  const modulus = 65521;
  const seedWeight = 127;
  const streamWeight = 8191;
  const midpoint = 32760;
  var hash = ((((particleId % f32(modulus)) + (seed * f32(seedWeight))) + f32((stream * streamWeight))) % f32(modulus));
  hash = (((hash * 251f) + 17f) % f32(modulus));
  hash = (((hash * 241f) + 31f) % f32(modulus));
  let finalMultiplier = ((hash % 127f) + 1f);
  hash = (((hash * finalMultiplier) + 97f) % f32(modulus));
  return ((hash / f32(midpoint)) - 1f);
}

struct SimulationData {
  stepInput: vec4f,
  emissionInput: vec4f,
  shapeInput: vec4f,
  shapeSpreadInput: vec4f,
  appearanceInput: vec4f,
  colorInput: vec4f,
  motionSpreadInput: vec4f,
  colorSpreadInput: vec4f,
  geometrySpreadInput: vec4f,
  positionInput: vec4f,
  transformInput: vec4f,
  orientationInput: vec4f,
  rotationCurve: array<vec4f, 17>,
  angularVelocityCurve: array<vec4f, 17>,
  modifiers: array<vec4f, 289>,
}

@group(0) @binding(0) var<uniform> data: SimulationData;

fn readCurve(curve: f32, index: f32) -> f32 {
  let word = i32(index);
  if ((curve < 0.5f)) {
    return data.rotationCurve[i32((f32(word) / 4f))][(word % 4i)];
  }
  return data.angularVelocityCurve[i32((f32(word) / 4f))][(word % 4i)];
}

fn advanceRotation(accumulatedRotation: f32, initialAngularVelocity: f32, age: f32, lifetime: f32, curve: f32, seconds: f32) -> f32 {
  const segmentCount = 64;
  var normalizedAge = 0f;
  if ((lifetime > 0f)) {
    normalizedAge = max(0f, min(1f, (age / lifetime)));
  }
  let samplePosition = (normalizedAge * f32(segmentCount));
  let segment = min(floor(samplePosition), f32((segmentCount - 1i)));
  let blend = (samplePosition - segment);
  let startMultiplier = readCurve(curve, segment);
  let endMultiplier = readCurve(curve, (segment + 1f));
  let multiplier = (startMultiplier + ((endMultiplier - startMultiplier) * blend));
  let rotationDelta = ((initialAngularVelocity * multiplier) * seconds);
  return (accumulatedRotation + rotationDelta);
}

fn spawnVariation(particleId: f32, seed: f32) -> f32 {
  const base = 4093;
  var left = ((floor((particleId / f32(base))) + floor((seed / f32(base)))) % f32(base));
  var right = (((particleId % f32(base)) + (seed % f32(base))) % f32(base));
  for (var round_1 = 0; (round_1 < 6i); round_1++) {
    let square = ((right * right) % f32(base));
    let mixed = (((square * 251f) + f32((round_1 * 1013i))) % f32(base));
    let next = ((left + mixed) % f32(base));
    left = right;
    right = next;
  }
  return (((left * f32(base)) + right) / f32((base * base)));
}

fn spawnCircle(particleId: f32, seed: f32, emitterX: f32, emitterY: f32, speed: f32, diameter: f32) -> vec4f {
  const fullCircle = 6.283185307179586;
  const radiusSeedOffset = 173;
  let angle = (spawnVariation(particleId, seed) * fullCircle);
  let radius = ((sqrt(spawnVariation(particleId, (seed + f32(radiusSeedOffset)))) * diameter) * 0.5f);
  let directionX = cos(angle);
  let directionY = sin(angle);
  let offsetX = (directionX * radius);
  let offsetY = (directionY * radius);
  let velocityX = (directionX * speed);
  let velocityY = (directionY * speed);
  return vec4f((emitterX + offsetX), (emitterY + offsetY), velocityX, velocityY);
}

fn spawnBox(particleId: f32, seed: f32, emitterX: f32, emitterY: f32, speed: f32, dimensionX: f32, dimensionY: f32) -> vec4f {
  let offsetX = ((spawnVariation(particleId, seed) - 0.5f) * dimensionX);
  let offsetY = ((spawnVariation(particleId, (seed + 173f)) - 0.5f) * dimensionY);
  return vec4f((emitterX + offsetX), (emitterY + offsetY), 0f, -(speed));
}

fn spawnCone2D(particleId: f32, seed: f32, emitterX: f32, emitterY: f32, speed: f32, dimensionX: f32, dimensionY: f32) -> vec4f {
  const sideSeedOffset = 173;
  let leftSample = spawnVariation(particleId, seed);
  let rightSample = spawnVariation(particleId, (seed + f32(sideSeedOffset)));
  let offsetX = (((rightSample - leftSample) * dimensionX) * 0.5f);
  var distanceUp = ((leftSample + rightSample) * dimensionY);
  if ((distanceUp > dimensionY)) {
    distanceUp = ((2f * dimensionY) - distanceUp);
  }
  let distanceFromTip = sqrt(((offsetX * offsetX) + (distanceUp * distanceUp)));
  if ((distanceFromTip == 0f)) {
    return vec4f(emitterX, emitterY, 0f, -(speed));
  }
  let velocityX = ((offsetX / distanceFromTip) * speed);
  let velocityY = ((-(distanceUp) / distanceFromTip) * speed);
  return vec4f((emitterX + offsetX), (emitterY - distanceUp), velocityX, velocityY);
}

fn spawnDirection(direction: f32, spread: f32, variation: f32) -> f32 {
  let centeredVariation = (variation - 0.5f);
  let angleOffset = (centeredVariation * spread);
  return (direction + angleOffset);
}

fn spawnMotion(particleId: f32, seed: f32, emitterX: f32, emitterY: f32, speed: f32, direction: f32, spread: f32) -> vec4f {
  let variation = spawnVariation(particleId, seed);
  let angle = spawnDirection(direction, spread, variation);
  let velocityX = (cos(angle) * speed);
  let velocityY = (sin(angle) * speed);
  return vec4f(emitterX, emitterY, velocityX, velocityY);
}

fn sampleShape(particleId: f32, seed: f32, shapeType: f32, direction: f32, spread: f32, dimensionX: f32, dimensionY: f32, dimensionSpreadX: f32, dimensionSpreadY: f32) -> vec4f {
  let sampledDimensionX = (dimensionX + (propertyVariation(particleId, seed, 12i) * dimensionSpreadX));
  let sampledDimensionY = (dimensionY + (propertyVariation(particleId, seed, 13i) * dimensionSpreadY));
  if ((shapeType == 1f)) {
    return spawnCircle(particleId, seed, 0f, 0f, 1f, sampledDimensionX);
  }
  if ((shapeType == 2f)) {
    return spawnBox(particleId, seed, 0f, 0f, 1f, sampledDimensionX, sampledDimensionY);
  }
  if ((shapeType == 3f)) {
    return spawnCone2D(particleId, seed, 0f, 0f, 1f, sampledDimensionX, sampledDimensionY);
  }
  return spawnMotion(particleId, seed, 0f, 0f, 1f, direction, spread);
}

fn spawnRotation(directionX: f32, directionY: f32) -> f32 {
  let clockwiseRadians = atan2(directionX, -(directionY));
  const radiansToDegrees = 57.29577951308232;
  return (-(clockwiseRadians) * radiansToDegrees);
}

fn movementRotation(velocityX: f32, velocityY: f32) -> f32 {
  const minimumSpeedSquared = 1e-4;
  const downwardTolerance = 1e-4;
  let speedSquared = ((velocityX * velocityX) + (velocityY * velocityY));
  if ((speedSquared <= minimumSpeedSquared)) {
    return 0f;
  }
  let speed = sqrt(speedSquared);
  let directionY = (velocityY / speed);
  if ((abs((1f - directionY)) <= downwardTolerance)) {
    return 180f;
  }
  let clockwiseRadians = atan2(velocityX, -(velocityY));
  const radiansToDegrees = 57.29577951308232;
  return (-(clockwiseRadians) * radiansToDegrees);
}

struct ParticleMotion {
  position: vec2f,
  velocity: vec2f,
  ageAfterStep: f32,
  lifetime: f32,
  initialRotation: f32,
  accumulatedRotation: f32,
  initialAngularVelocity: f32,
  modifierVariation: f32,
  handedness: f32,
}

fn readModifier(index: f32) -> f32 {
  let word = i32(index);
  return data.modifiers[i32((f32(word) / 4f))][(word % 4i)];
}

fn particleHeading(baseRotation: f32, age: f32, lifetime: f32, rotationCurve: f32, velocityX: f32, velocityY: f32, orientToMovement: f32, handedness: f32) -> vec2f {
  const segmentCount = 64;
  var normalizedAge = 0f;
  if ((lifetime > 0f)) {
    normalizedAge = max(0f, min(1f, (age / lifetime)));
  }
  let samplePosition = (normalizedAge * f32(segmentCount));
  let segment = min(floor(samplePosition), f32((segmentCount - 1i)));
  let blend = (samplePosition - segment);
  let startRotation = readCurve(rotationCurve, segment);
  let endRotation = readCurve(rotationCurve, (segment + 1f));
  let lifetimeRotation = (startRotation + ((endRotation - startRotation) * blend));
  var movementAlignment = 0f;
  if ((orientToMovement > 0.5f)) {
    movementAlignment = movementRotation(velocityX, velocityY);
  }
  let rotationDegrees = ((baseRotation + (lifetimeRotation * handedness)) + movementAlignment);
  let clockwiseRadians = ((-(rotationDegrees) * 3.141592653589793f) / 180f);
  return vec2f(sin(clockwiseRadians), -(cos(clockwiseRadians)));
}

fn applyAcceleration(directionComponent: f32, magnitude: f32, spread: f32, spreadFactor: f32) -> f32 {
  let sampledMagnitude = (magnitude + (spread * spreadFactor));
  return (directionComponent * sampledMagnitude);
}

fn applyDrag(velocity: f32, velocityToDamp: f32, magnitude: f32, spread: f32, spreadFactor: f32, seconds: f32) -> f32 {
  let sampledRate = (magnitude + (spread * spreadFactor));
  let dampingFraction = min((sampledRate * seconds), 1f);
  return (velocity - (velocityToDamp * dampingFraction));
}

fn applyDragVelocity(velocity: vec2f, direction: vec2f, magnitude: f32, spread: f32, spreadFactor: f32, seconds: f32, directional: f32) -> vec2f {
  var velocityToDampX = velocity[0i];
  var velocityToDampY = velocity[1i];
  if ((directional > 0.5f)) {
    let speedAlongDirection = ((velocity[0i] * direction[0i]) + (velocity[1i] * direction[1i]));
    velocityToDampX = (speedAlongDirection * direction[0i]);
    velocityToDampY = (speedAlongDirection * direction[1i]);
  }
  return vec2f(applyDrag(velocity[0i], velocityToDampX, magnitude, spread, spreadFactor, seconds), applyDrag(velocity[1i], velocityToDampY, magnitude, spread, spreadFactor, seconds));
}

fn applyRadial(x: f32, y: f32, centerX: f32, centerY: f32, headingX: f32, headingY: f32, magnitude: f32, spread: f32, spreadFactor: f32, maxDistance: f32) -> vec2f {
  let offsetX = (x - centerX);
  let offsetY = (y - centerY);
  let distanceSquared = ((offsetX * offsetX) + (offsetY * offsetY));
  let maxDistanceSquared = (maxDistance * maxDistance);
  if ((distanceSquared > maxDistanceSquared)) {
    return vec2f();
  }
  let sampledMagnitude = (magnitude + (spread * spreadFactor));
  if ((distanceSquared == 0f)) {
    return vec2f((headingX * sampledMagnitude), (headingY * sampledMagnitude));
  }
  let distance_1 = sqrt(distanceSquared);
  let directionX = (offsetX / distance_1);
  let directionY = (offsetY / distance_1);
  return vec2f((directionX * sampledMagnitude), (directionY * sampledMagnitude));
}

fn applyVortex(x: f32, y: f32, centerX: f32, centerY: f32, fallbackDirectionX: f32, fallbackDirectionY: f32, magnitude: f32, spread: f32, spreadFactor: f32, maxDistance: f32) -> vec2f {
  let offsetX = (x - centerX);
  let offsetY = (y - centerY);
  let distanceSquared = ((offsetX * offsetX) + (offsetY * offsetY));
  let maxDistanceSquared = (maxDistance * maxDistance);
  if ((distanceSquared > maxDistanceSquared)) {
    return vec2f();
  }
  let sampledMagnitude = (magnitude + (spread * spreadFactor));
  if ((distanceSquared == 0f)) {
    return vec2f((fallbackDirectionX * sampledMagnitude), (fallbackDirectionY * sampledMagnitude));
  }
  let distance_1 = sqrt(distanceSquared);
  let tangentX = (offsetY / distance_1);
  let tangentY = (-(offsetX) / distance_1);
  return vec2f((tangentX * sampledMagnitude), (tangentY * sampledMagnitude));
}

fn dispatchModifier(position: vec2f, velocity: vec2f, heading: vec2f, spreadFactor: f32, seconds: f32, offset: f32) -> vec2f {
  const accelerationType = 0;
  const dragType = 1;
  const radialType = 2;
  const vortexType = 3;
  let type_1 = readModifier(offset);
  let magnitude = readModifier((offset + 1f));
  let spread = readModifier((offset + 2f));
  let directionX = readModifier((offset + 5f));
  let directionY = readModifier((offset + 6f));
  if ((type_1 == f32(accelerationType))) {
    return vec2f((velocity[0i] + (applyAcceleration(directionX, magnitude, spread, spreadFactor) * seconds)), (velocity[1i] + (applyAcceleration(directionY, magnitude, spread, spreadFactor) * seconds)));
  }
  if ((type_1 == f32(dragType))) {
    let directional = readModifier((offset + 8f));
    return applyDragVelocity(velocity, vec2f(directionX, directionY), magnitude, spread, spreadFactor, seconds, directional);
  }
  let centerX = readModifier((offset + 3f));
  let centerY = readModifier((offset + 4f));
  let maxDistance = readModifier((offset + 7f));
  var acceleration = vec2f();
  if ((type_1 == f32(radialType))) {
    acceleration = applyRadial(position[0i], position[1i], centerX, centerY, heading[0i], heading[1i], magnitude, spread, spreadFactor, maxDistance);
  }
  else {
    if ((type_1 == f32(vortexType))) {
      acceleration = applyVortex(position[0i], position[1i], centerX, centerY, directionX, directionY, magnitude, spread, spreadFactor, maxDistance);
    }
    else {
      return velocity;
    }
  }
  return vec2f((velocity[0i] + (acceleration[0i] * seconds)), (velocity[1i] + (acceleration[1i] * seconds)));
}

fn applyModifiers(x: f32, y: f32, velocityX: f32, velocityY: f32, headingX: f32, headingY: f32, spreadFactor: f32, seconds: f32) -> vec2f {
  let count = readModifier(0f);
  const headerSize = 2;
  const recordSize = 9;
  let position = vec2f(x, y);
  let heading = vec2f(headingX, headingY);
  var velocity = vec2f(velocityX, velocityY);
  for (var index = 0; (index < 128i); index++) {
    if ((f32(index) >= count)) {
      break;
    }
    let offset = (headerSize + (index * recordSize));
    velocity = dispatchModifier(position, velocity, heading, spreadFactor, seconds, f32(offset));
  }
  return velocity;
}

fn integrateMotion(particle: ParticleMotion, step_1: ParticleStep) -> vec4f {
  let modifierCount = readModifier(0f);
  if ((modifierCount == 0f)) {
    return vec4f((particle.position.x + (particle.velocity.x * step_1.seconds)), (particle.position.y + (particle.velocity.y * step_1.seconds)), particle.velocity.x, particle.velocity.y);
  }
  let containsRadial = readModifier(1f);
  var heading = vec2f(0, -1);
  if ((containsRadial > 0f)) {
    var angularRotation = 0f;
    if ((step_1.orientToAngularVelocity > 0.5f)) {
      let rotationAfterStep = advanceRotation(particle.accumulatedRotation, particle.initialAngularVelocity, particle.ageAfterStep, particle.lifetime, step_1.angularVelocityCurve, step_1.seconds);
      angularRotation = (rotationAfterStep * particle.handedness);
    }
    let baseRotation = (particle.initialRotation + angularRotation);
    heading = particleHeading(baseRotation, particle.ageAfterStep, particle.lifetime, step_1.rotationCurve, particle.velocity.x, particle.velocity.y, step_1.orientToMovement, particle.handedness);
  }
  let nextVelocity = applyModifiers(particle.position.x, particle.position.y, particle.velocity.x, particle.velocity.y, heading.x, heading.y, particle.modifierVariation, step_1.seconds);
  let nextX = (particle.position.x + (nextVelocity.x * step_1.seconds));
  let nextY = (particle.position.y + (nextVelocity.y * step_1.seconds));
  return vec4f(nextX, nextY, nextVelocity.x, nextVelocity.y);
}

fn initializeParticle(band: f32, particleId: f32, birth: ParticleBirth, step_1: ParticleStep) -> vec4f {
  if ((band == 3f)) {
    let angularVelocity = (birth.initialAngularVelocity + (propertyVariation(particleId, birth.seed, 15i) * birth.angularVelocitySpread));
    var rotation = 0f;
    if ((step_1.orientToAngularVelocity > 0.5f)) {
      let sampledLifetime = (birth.lifetime + (propertyVariation(particleId, birth.seed, 2i) * birth.lifetimeSpread));
      rotation = advanceRotation(0f, angularVelocity, step_1.seconds, sampledLifetime, step_1.angularVelocityCurve, step_1.seconds);
    }
    return vec4f(1f, propertyVariation(particleId, birth.seed, 14i), angularVelocity, rotation);
  }
  if ((band == 2f)) {
    return vec4f((birth.initialRed + (propertyVariation(particleId, birth.seed, 5i) * birth.redSpread)), (birth.initialGreen + (propertyVariation(particleId, birth.seed, 6i) * birth.greenSpread)), (birth.initialBlue + (propertyVariation(particleId, birth.seed, 7i) * birth.blueSpread)), (birth.initialAlpha + (propertyVariation(particleId, birth.seed, 8i) * birth.alphaSpread)));
  }
  let sampledLifetime = (birth.lifetime + (propertyVariation(particleId, birth.seed, 2i) * birth.lifetimeSpread));
  let shape = sampleShape(particleId, birth.seed, birth.shapeType, birth.direction, birth.spread, birth.dimensionX, birth.dimensionY, birth.dimensionSpreadX, birth.dimensionSpreadY);
  var rotation = (birth.initialRotation + ((propertyVariation(particleId, birth.seed, 4i) * birth.rotationSpread) * birth.handedness));
  if ((birth.orientToDirection > 0.5f)) {
    rotation += (spawnRotation(shape.z, shape.w) * birth.handedness);
  }
  if ((band == 1f)) {
    let sampledSize = (birth.initialSize + (propertyVariation(particleId, birth.seed, 3i) * birth.sizeSpread));
    return vec4f(step_1.seconds, sampledLifetime, (sampledSize * birth.emitterScale), rotation);
  }
  let sampledSpeed = ((birth.speed + (propertyVariation(particleId, birth.seed, 1i) * birth.speedSpread)) * birth.emitterScale);
  let birthSpreadFactor = propertyVariation(particleId, birth.seed, 14i);
  let birthVelocityX = (((((birth.emitterCosine * shape.z) * birth.handedness) - (birth.emitterSine * shape.w)) * sampledSpeed) + birth.inheritedVelocityX);
  let birthVelocityY = (((((birth.emitterSine * shape.z) * birth.handedness) + (birth.emitterCosine * shape.w)) * sampledSpeed) + birth.inheritedVelocityY);
  if ((band == 4f)) {
    var birthHeading = 0f;
    if ((step_1.orientToMovement > 0.5f)) {
      birthHeading = movementRotation(birthVelocityX, birthVelocityY);
    }
    return vec4f((birth.initialStretchX + (propertyVariation(particleId, birth.seed, 16i) * birth.stretchXSpread)), (birth.initialStretchY + (propertyVariation(particleId, birth.seed, 17i) * birth.stretchYSpread)), birth.handedness, birthHeading);
  }
  let positionX = (birth.emitterX + ((((birth.emitterCosine * shape.x) * birth.handedness) - (birth.emitterSine * shape.y)) * birth.emitterScale));
  let positionY = (birth.emitterY + ((((birth.emitterSine * shape.x) * birth.handedness) + (birth.emitterCosine * shape.y)) * birth.emitterScale));
  let angularVelocity = (birth.initialAngularVelocity + (propertyVariation(particleId, birth.seed, 15i) * birth.angularVelocitySpread));
  let particle = ParticleMotion(vec2f(positionX, positionY), vec2f(birthVelocityX, birthVelocityY), step_1.seconds, sampledLifetime, rotation, 0f, angularVelocity, birthSpreadFactor, birth.handedness);
  return integrateMotion(particle, step_1);
}

fn readState(state: texture_2d<f32>, birth: texture_2d<f32>, birthPass: f32, rows: f32, x: f32, y: f32) -> vec4f {
  if ((birthPass > 0.5f)) {
    return vec4f();
  }
  let row = (i32(y) % i32(rows));
  let band = i32((f32(i32(y)) / f32(i32(rows))));
  let p = vec2i(i32(x), row);
  let dynamic = textureLoad(state, vec2i(p.x, (row + i32(rows))), 0);
  let b0 = textureLoad(birth, p, 0);
  let b2 = textureLoad(birth, vec2i(p.x, (row + (i32(rows) * 2i))), 0);
  if ((band == 0i)) {
    return textureLoad(state, p, 0);
  }
  if ((band == 1i)) {
    return vec4f(dynamic.x, b0.x, b0.y, b0.z);
  }
  if ((band == 2i)) {
    return textureLoad(birth, vec2i(p.x, (row + i32(rows))), 0);
  }
  if ((band == 3i)) {
    return vec4f(dynamic.y, b0.w, b2.x, dynamic.z);
  }
  return vec4f(b2.y, b2.z, b2.w, dynamic.w);
}

struct ParticleAddress {
  band: f32,
  column: f32,
  row: f32,
  rows: f32,
}

fn advanceAge(age: f32, seconds: f32) -> f32 {
  return (age + seconds);
}

fn particleAlive(age: f32, lifetime: f32) -> f32 {
  if ((age > lifetime)) {
    return 0f;
  }
  return 1f;
}

fn advanceParticle(state: texture_2d<f32>, birthState: texture_2d<f32>, birthPass: f32, address: ParticleAddress, step_1: ParticleStep) -> vec4f {
  let properties = readState(state, birthState, birthPass, address.rows, address.column, (address.row + (address.rows * 1f)));
  let dynamics = readState(state, birthState, birthPass, address.rows, address.column, (address.row + (address.rows * 3f)));
  let age = properties.x;
  let lifetime = properties.y;
  let initialSize = properties.z;
  let initialRotation = properties.w;
  let wasActive = dynamics.x;
  let modifierVariation = dynamics.y;
  let angularVelocity = dynamics.z;
  let accumulatedRotation = dynamics.w;
  let active_1 = (wasActive * particleAlive(advanceAge(age, step_1.seconds), lifetime));
  if ((address.band == 4f)) {
    let geometry = readState(state, birthState, birthPass, address.rows, address.column, (address.row + (address.rows * 4f)));
    if (((step_1.orientToMovement > 0.5f) && (active_1 > 0.5f))) {
      let previousMotion = readState(state, birthState, birthPass, address.rows, address.column, address.row);
      return vec4f(geometry.x, geometry.y, geometry.z, movementRotation(previousMotion.z, previousMotion.w));
    }
    return geometry;
  }
  if ((address.band == 3f)) {
    if (((step_1.orientToAngularVelocity > 0.5f) && (active_1 > 0.5f))) {
      return vec4f(active_1, modifierVariation, angularVelocity, advanceRotation(accumulatedRotation, angularVelocity, (age + step_1.seconds), lifetime, step_1.angularVelocityCurve, step_1.seconds));
    }
    return vec4f(active_1, modifierVariation, angularVelocity, accumulatedRotation);
  }
  if ((address.band == 2f)) {
    return readState(state, birthState, birthPass, address.rows, address.column, (address.row + (address.rows * 2f)));
  }
  if ((address.band == 1f)) {
    return vec4f(advanceAge(age, step_1.seconds), lifetime, initialSize, initialRotation);
  }
  let motion = readState(state, birthState, birthPass, address.rows, address.column, address.row);
  if ((active_1 < 0.5f)) {
    return vec4f(motion.x, motion.y, 0f, 0f);
  }
  let geometry = readState(state, birthState, birthPass, address.rows, address.column, (address.row + (address.rows * 4f)));
  let particle = ParticleMotion(vec2f(motion.x, motion.y), vec2f(motion.z, motion.w), (age + step_1.seconds), lifetime, initialRotation, accumulatedRotation, angularVelocity, modifierVariation, geometry.z);
  return integrateMotion(particle, step_1);
}

fn integrate(state: texture_2d<f32>, stepInput: vec4f, emissionInput: vec4f, shapeInput: vec4f, shapeSpreadInput: vec4f, appearanceInput: vec4f, colorInput: vec4f, motionSpreadInput: vec4f, colorSpreadInput: vec4f, geometrySpreadInput: vec4f, positionInput: vec4f, transformInput: vec4f, orientationInput: vec4f, spawnMask: texture_2d<f32>, rotationCurve: f32, angularVelocityCurve: f32, threadX: f32, threadY: f32, width: f32, rows: f32, capacity: f32, birthState: texture_2d<f32>, birthPass: f32) -> vec4f {
  let seconds = stepInput[0i];
  let spawnCount = stepInput[1i];
  let band = floor((threadY / rows));
  let particleRow = (threadY % rows);
  let particleId = ((particleRow * width) + threadX);
  let spawnWord = readSpawn(spawnMask, floor((particleId / 24f)));
  let spawnBit = (floor((spawnWord / pow(2f, (particleId % 24f)))) % 2f);
  let isSpawning = (((particleId < capacity) && (spawnCount > 0f)) && (spawnBit > 0.5f));
  let step_1 = ParticleStep(stepInput[0i], orientationInput[1i], orientationInput[2i], rotationCurve, angularVelocityCurve);
  if (isSpawning) {
    let birth = ParticleBirth(stepInput[2i], emissionInput[0i], emissionInput[1i], emissionInput[2i], emissionInput[3i], shapeInput[0i], shapeInput[1i], shapeInput[2i], shapeSpreadInput[0i], shapeSpreadInput[1i], appearanceInput[0i], appearanceInput[1i], appearanceInput[2i], appearanceInput[3i], colorInput[0i], colorInput[1i], colorInput[2i], colorInput[3i], motionSpreadInput[0i], motionSpreadInput[1i], motionSpreadInput[2i], motionSpreadInput[3i], colorSpreadInput[0i], colorSpreadInput[1i], colorSpreadInput[2i], colorSpreadInput[3i], geometrySpreadInput[0i], geometrySpreadInput[1i], geometrySpreadInput[2i], positionInput[0i], positionInput[1i], positionInput[2i], positionInput[3i], transformInput[0i], transformInput[1i], transformInput[2i], transformInput[3i], orientationInput[0i], orientationInput[3i]);
    return initializeParticle(band, particleId, birth, step_1);
  }
  if ((seconds == 0f)) {
    return readState(state, birthState, birthPass, rows, threadX, threadY);
  }
  let address = ParticleAddress(band, threadX, particleRow, rows);
  return advanceParticle(state, birthState, birthPass, address, step_1);
}

struct Dimensions { width: u32, rows: u32, capacity: u32, padding: u32 }
@group(1) @binding(0) var previousState: texture_2d<f32>;
@group(1) @binding(1) var spawnMask: texture_2d<f32>;
@group(1) @binding(2) var birthState: texture_2d<f32>;
@group(1) @binding(3) var outputState: texture_storage_2d<rgba32float, write>;
@group(1) @binding(4) var<uniform> dimensions: Dimensions;

fn evaluateBand(address: vec2u, band: u32, birthPass: f32) -> vec4f {
  return integrate(previousState,
    data.stepInput, data.emissionInput, data.shapeInput, data.shapeSpreadInput,
    data.appearanceInput, data.colorInput, data.motionSpreadInput, data.colorSpreadInput,
    data.geometrySpreadInput, data.positionInput, data.transformInput, data.orientationInput,
    spawnMask, 0.0, 1.0, f32(address.x), f32(address.y + dimensions.rows * band),
    f32(dimensions.width), f32(dimensions.rows), f32(dimensions.capacity), birthState, birthPass);
}

// Only recycled slots are written. Existing birth properties remain untouched.
@compute @workgroup_size(8, 8)
fn births(@builtin(global_invocation_id) id: vec3u) {
  if (id.x >= dimensions.width || id.y >= dimensions.rows) { return; }
  let slot = id.y * dimensions.width + id.x;
  let mask = u32(readSpawn(spawnMask, f32(slot / 24u)));
  if (slot >= dimensions.capacity || (mask & (1u << (slot % 24u))) == 0u) { return; }
  let properties = evaluateBand(id.xy, 1u, 1.0);
  let dynamics = evaluateBand(id.xy, 3u, 1.0);
  let geometry = evaluateBand(id.xy, 4u, 1.0);
  textureStore(outputState, vec2i(id.xy), vec4f(properties.yzw, dynamics.y));
  textureStore(outputState, vec2i(id.xy + vec2u(0u, dimensions.rows)), evaluateBand(id.xy, 2u, 1.0));
  textureStore(outputState, vec2i(id.xy + vec2u(0u, dimensions.rows * 2u)), vec4f(dynamics.z, geometry.xyz));
}

// Each invocation advances one slot and writes its two changing-state bands.
@compute @workgroup_size(8, 8)
fn advance(@builtin(global_invocation_id) id: vec3u) {
  if (id.x >= dimensions.width || id.y >= dimensions.rows) { return; }
  let age = evaluateBand(id.xy, 1u, 0.0).x;
  let dynamics = evaluateBand(id.xy, 3u, 0.0);
  let heading = evaluateBand(id.xy, 4u, 0.0).w;
  textureStore(outputState, vec2i(id.xy), evaluateBand(id.xy, 0u, 0.0));
  textureStore(outputState, vec2i(id.xy + vec2u(0u, dimensions.rows)), vec4f(age, dynamics.x, dynamics.w, heading));
}
